/* From Uiverse.io by andrew-demchenk0 - Tags: animation, blue, twitter, button, hover effect, tweet */
.__UIV_SCOPE__ button {
  width: 100px;
  height: 32px;
  background-color: #55acee;
  border-radius: 4px;
  border: none;
  cursor: pointer;
  display: flex;
  align-items: center;
  padding: 0 8px;
  justify-content: space-between;
  transition: all 0.3s;
}

.__UIV_SCOPE__ button:hover {
  opacity: 0.85;
  transform: translateY(-4px);
}

.__UIV_SCOPE__ button .label {
  font-size: 12px;
  line-height: 32px;
  color: #fff;
  font-weight: 700;
  letter-spacing: 1px;
  margin: 0 auto;
}

.__UIV_SCOPE__ button svg {
  fill: #fff;
  width: 30px;
  height: 30px;
}
